script:
(function () {
  'use strict';
  // Investment solver (time value of money). With i = return per contribution period and n periods:
  //   End = Start(1 + i)^n + C x [((1 + i)^n - 1) / i] x (1 + i if contributions are at the start)
  // Given any four of End, Start, C, rate and years it finds the fifth: Start and C in closed form,
  // the rate by bisection (End rises steadily with the rate) and the years by stepping period by
  // period until the balance reaches the target. i = (1 + r/m)^(m/p) - 1 for m compounding periods
  // and p contributions a year (e^(r/p) - 1 when continuous); the solved rate is converted back.
  // Checked in Node (iv.test.js): $10,000 + $500/month, 6% a year compounded yearly, 20 years =
  // $258,790.67 (closed form above); solving back from that ending amount returns $10,000, $500,
  // 6.0000% and 20 years; $1,000 at 7.2% yearly doubles in 10 years (1.072^10 = 2.004);
  // $100/month for 30 years at 6% compounded monthly = $100,451.50 (textbook annuity value);
  // 0% rate gives the plain sum and the 0% years answer (target - start) / C.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });
  var MAX_YEARS = 100;
  var LABELS = { end: 'Ending amount', start: 'Starting amount needed', contrib: 'Contribution needed',
                 rate: 'Annual return needed', years: 'Time needed' };
  var FIELDS = { end: 'ivTargetField', start: 'ivStartField', contrib: 'ivContribField', rate: 'ivRateField', years: 'ivYearsField' };
  var MODES = ['end', 'start', 'contrib', 'rate', 'years'];
  var OUTPUTS = ['ivAnswer', 'ivPaidIn', 'ivGrowth', 'ivEnd', 'ivReal', 'ivStartOut', 'ivContribOut', 'ivEffective', 'ivTime'];
  var RADIOS = { end: 'ivSolveEnd', start: 'ivSolveStart', contrib: 'ivSolveContrib', rate: 'ivSolveRate', years: 'ivSolveYears' };

  // --- calc start
  function periodRate(annualRate, compPerYear, perYear) {
    if (compPerYear === 0) return Math.exp(annualRate / perYear) - 1;
    return Math.pow(1 + annualRate / compPerYear, compPerYear / perYear) - 1;
  }

  function annualFromPeriod(i, compPerYear, perYear) {
    if (compPerYear === 0) return perYear * Math.log(1 + i);
    return compPerYear * (Math.pow(1 + i, perYear / compPerYear) - 1);
  }

  // Factor that turns one contribution per period into an ending amount.
  function annuityFactor(i, n, due) {
    var f = Math.abs(i) < 1e-12 ? n : (Math.pow(1 + i, n) - 1) / i;
    return due ? f * (1 + i) : f;
  }

  function endValue(start, c, i, n, due) {
    return start * Math.pow(1 + i, n) + c * annuityFactor(i, n, due);
  }

  function solveStart(target, c, i, n, due) {
    return (target - c * annuityFactor(i, n, due)) / Math.pow(1 + i, n);
  }

  function solveContribution(target, start, i, n, due) {
    return (target - start * Math.pow(1 + i, n)) / annuityFactor(i, n, due);
  }

  // Per-period rate that grows start and c to target over n periods; null if none in range.
  function solvePeriodRate(target, start, c, n, due) {
    var lo = -0.9999, hi = 1;
    if (endValue(start, c, lo, n, due) > target) return null;
    while (endValue(start, c, hi, n, due) < target) { hi *= 2; if (hi > 1e6) return null; }
    for (var k = 0; k < 300; k++) {
      var mid = (lo + hi) / 2;
      if (endValue(start, c, mid, n, due) < target) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }

  // Number of whole periods until the balance first reaches target (0 if it already has); null if never.
  function solvePeriods(target, start, c, i, due, maxPeriods) {
    if (start >= target) return 0;
    var bal = start;
    for (var k = 1; k <= maxPeriods; k++) {
      bal = due ? (bal + c) * (1 + i) : bal * (1 + i) + c;
      if (bal >= target - 1e-7) return k;
    }
    return null;
  }

  function schedule(start, c, i, n, perYear, due) {
    var bal = start, rows = [], yC = 0, yG = 0;
    for (var k = 1; k <= n; k++) {
      var g;
      if (due) { bal += c; g = bal * i; bal += g; } else { g = bal * i; bal += g + c; }
      yC += c; yG += g;
      if (k % perYear === 0 || k === n) { rows.push({ year: k / perYear, contrib: yC, growth: yG, balance: bal }); yC = 0; yG = 0; }
    }
    return { end: bal, rows: rows };
  }
  // --- calc end

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function pct(x) { return (x * 100).toFixed(2).replace(/\.?0+$/, '') + '%'; }

  function duration(periods, perYear) {
    if (perYear === 1 || periods === 0) return periods + (periods === 1 ? ' year' : ' years');
    var months = Math.round(periods / perYear * 12), y = Math.floor(months / 12), m = months % 12;
    var parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (!y && !m) return '0 years';
    if (m) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function mode() {
    for (var k = 0; k < MODES.length; k++) if (document.getElementById(RADIOS[MODES[k]]).checked) return MODES[k];
    return 'end';
  }

  function fail(msg) {
    var error = document.getElementById('ivError');
    error.hidden = false;
    error.textContent = msg;
    OUTPUTS.forEach(function (id) { document.getElementById(id).textContent = '–'; });
    document.getElementById('ivSchedule').innerHTML = '';
  }

  function update() {
    var solve = mode();
    MODES.forEach(function (m) { document.getElementById(FIELDS[m]).hidden = m === solve; });
    document.getElementById('ivAnswerLabel').textContent = LABELS[solve];
    var note = document.getElementById('ivNote');
    note.hidden = true;
    document.getElementById('ivError').hidden = true;

    var target = num('ivTarget'), start = num('ivStart'), c = num('ivContrib'), rate = num('ivRate'),
        years = num('ivYears'), infl = num('ivInflation');
    var perYear = parseInt(document.getElementById('ivFreq').value, 10);
    var compVal = document.getElementById('ivComp').value;
    var comp = compVal === 'same' ? perYear : parseInt(compVal, 10);
    var due = document.getElementById('ivTiming').value === 'begin';
    var need = { end: [start, c, rate, years], start: [target, c, rate, years], contrib: [target, start, rate, years],
                 rate: [target, start, c, years], years: [target, start, c, rate] }[solve];
    if (need.some(isNaN) || isNaN(infl)) return fail('Fill in every visible field with a number.');
    if (solve !== 'start' && start < 0) return fail('The starting amount cannot be negative.');
    if (solve !== 'contrib' && c < 0) return fail('The contribution cannot be negative.');
    if (solve !== 'end' && target <= 0) return fail('Enter a target ending amount above $0.');
    if (solve !== 'rate' && (rate < -50 || rate > 100)) return fail('Enter an annual return from -50% to 100%.');
    if (solve !== 'years' && (years < 1 || years > MAX_YEARS)) return fail('Enter 1 to 100 years.');
    if (infl < 0 || infl > 20) return fail('Enter an inflation rate from 0 to 20%.');

    var i = solve === 'rate' ? 0 : periodRate(rate / 100, comp, perYear);
    var n = Math.round(years * perYear);
    if (solve === 'end') {
      if (start + c <= 0) return fail('Enter a starting amount, a contribution or both.');
    } else if (solve === 'start') {
      start = solveStart(target, c, i, n, due);
      if (start < 0) { start = 0; note.hidden = false; note.textContent = 'Your contributions alone are projected to pass the target, so no starting amount is needed.'; }
    } else if (solve === 'contrib') {
      c = solveContribution(target, start, i, n, due);
      if (c < 0) { c = 0; note.hidden = false; note.textContent = 'Your starting amount alone is projected to pass the target, so no further contributions are needed.'; }
    } else if (solve === 'rate') {
      if (start + c <= 0) return fail('Enter a starting amount, a contribution or both.');
      i = solvePeriodRate(target, start, c, n, due);
      if (i === null) return fail('No return rate can reach that target with these amounts. Check the target and the amounts.');
      rate = annualFromPeriod(i, comp, perYear) * 100;
    } else {
      if (start + c <= 0) return fail('Enter a starting amount, a contribution or both.');
      n = solvePeriods(target, start, c, i, due, MAX_YEARS * perYear);
      if (n === null) return fail('At these numbers the target is not reached within 100 years.');
      if (n === 0) { note.hidden = false; note.textContent = 'Your starting amount already meets the target.'; }
      years = n / perYear;
    }

    var s = schedule(start, c, i, n, perYear, due);
    if (!isFinite(s.end) || !isFinite(start) || !isFinite(c) || Math.abs(s.end) > 1e15) return fail('That result is too large to show. Try smaller numbers.');
    var paidIn = start + c * n;
    var answer = { end: money.format(s.end), start: money.format(start), contrib: money.format(c),
                   rate: pct(rate / 100), years: duration(n, perYear) }[solve];
    document.getElementById('ivAnswer').textContent = answer;
    document.getElementById('ivPaidIn').textContent = money.format(paidIn);
    document.getElementById('ivGrowth').textContent = money.format(s.end - paidIn);
    document.getElementById('ivEnd').textContent = money.format(s.end);
    document.getElementById('ivReal').textContent = money.format(s.end / Math.pow(1 + infl / 100, years));
    document.getElementById('ivStartOut').textContent = money.format(start);
    document.getElementById('ivContribOut').textContent = whole.format(n) + ' × ' + money.format(c);
    document.getElementById('ivEffective').textContent = pct(Math.pow(1 + i, perYear) - 1);
    document.getElementById('ivTime').textContent = duration(n, perYear);
    document.getElementById('ivSchedule').innerHTML = s.rows.map(function (row) {
      var label = Math.abs(row.year - Math.round(row.year)) < 1e-9 ? String(Math.round(row.year)) : Math.ceil(row.year) + ' (part)';
      return '<tr><td>' + label + '</td><td>' + money.format(row.contrib) + '</td><td>' +
             money.format(row.growth) + '</td><td>' + money.format(row.balance) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('ivForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
